const words=list=>list.flatMap(word=>[word,word.toUpperCase()]).join("|");const keywordList=["select","insert","update","delete","from","where","join","inner","left","right","full","outer","cross","on","group","by","order","having","limit","offset","union","all","distinct","as","and","or","not","is","in","like","between","exists","case","when","then","else","end","with","into","values","set","create","table","alter","drop","add","column","index","view","primary","key","foreign","references","constraint","default","unique","check","cascade","trigger","procedure","function","returns","begin","commit","rollback","transaction","grant","revoke","asc","desc","if"];const typeList=["int","integer","bigint","smallint","tinyint","decimal","numeric","float","double","real","boolean","bit","char","varchar","text","date","datetime","timestamp","time","blob","json","uuid","serial"];export default{scopeName:"source.sql",patterns:[{include:"#comments"},{include:"#strings"},{include:"#constants"},{include:"#keywords"},{include:"#types"},{include:"#numbers"},{include:"#operators"},{include:"#function-call"}],repository:{comments:{patterns:[{match:"--.*$",name:"comment.line.double-dash"},{begin:"/\\*",end:"\\*/",name:"comment.block"}]},strings:{patterns:[{match:"'(?:''|\\\\.|[^'\\\\])*'",name:"string.quoted.single"},{match:'"(?:""|[^"])*"',name:"string.quoted.double"}]},keywords:{match:`\\b(?:${words(keywordList)})\\b`,name:"keyword.control"},types:{match:`\\b(?:${words(typeList)})\\b`,name:"support.class.builtin"},constants:{patterns:[{match:`\\b(?:${words(["true","false"])})\\b`,name:"constant.language.boolean"},{match:`\\b(?:${words(["null"])})\\b`,name:"constant.language"}]},numbers:{match:"(?<![\\w.])-?\\d+(?:\\.\\d+)?\\b",name:"constant.numeric"},operators:{match:"(?:<>|!=|<=|>=|\\|\\||[=<>+\\-*/%])",name:"keyword.operator"},"function-call":{match:"\\b[A-Za-z_]\\w*(?=\\s*\\()",name:"entity.name.function"}}};
